create or replace function private.schoolpro_cached_readable_students() returns uuid[] language sql stable security definer set search_path='' as $$select coalesce(array_agg(s.id),array[]::uuid[]) from public.schoolpro_students s where auth.uid() is not null and private.schoolpro_can_read_student(s.id)$$;
revoke all on function private.schoolpro_cached_readable_students() from public,anon;
grant execute on function private.schoolpro_cached_readable_students() to authenticated,service_role;
alter policy "Result reader access" on public.schoolpro_results using(case when school_id=any((select private.schoolpro_cached_access_schools('results','result-leader'))::uuid[]) then true else student_id=any((select private.schoolpro_cached_readable_students())::uuid[]) and private.schoolpro_result_reader_matches(school_id,student_id,subject_id,session,status,locked) end);
alter policy "Result access gate" on public.schoolpro_results using((select private.is_active_account()) and case when school_id=any((select private.schoolpro_cached_access_schools('results','result-leader'))::uuid[]) then true else student_id=any((select private.schoolpro_cached_readable_students())::uuid[]) and coalesce((select a.allowed from private.schoolpro_result_access(schoolpro_results.student_id,schoolpro_results.term,schoolpro_results.session) a),false) end);
